package keystrokesmod.script.packet.serverbound;
import keystrokesmod.script.model.ItemStack; import net.minecraft.network.play.client.C0EPacketClickWindow;
public class C0E extends CPacket { public int windowId,slot,button,mode; public short action; public ItemStack itemStack; public C0E(int id,int slot,int button,int mode,ItemStack item){super(new C0EPacketClickWindow(id,slot,button,mode,item==null?null:item.itemStack,(short)0));windowId=id;this.slot=slot;this.button=button;this.mode=mode;itemStack=item;} public C0E(C0EPacketClickWindow value){super(value);windowId=value.getWindowId();slot=value.getSlotId();button=value.getUsedButton();action=value.getActionNumber();itemStack=ItemStack.convert(value.getClickedItem());} public C0EPacketClickWindow convert(){return (C0EPacketClickWindow)packet;} }
